const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const output = {
  event: 'github.issue_labeled',
  source: 'github',
  repo: body.repository?.full_name ?? body.repo ?? 'div0rce/cherry',
  timestamp: body.timestamp ?? body.workflow_run?.updated_at ?? body.pull_request?.updated_at ?? body.issue?.updated_at ?? new Date().toISOString(),
  payload: body,
  workflow: '02_openclaw_issue_router',
  ok: true,
  status: 'accepted',
  summary: 'Normalized github.issue_labeled.',
  actions: []
};
return [{ json: output }];

const event = $input.first()?.json ?? {};
const fields = ["payload.issue.number","payload.issue.title"];
const missing = fields.filter((field) => field.split('.').reduce((value, key) => value?.[key], event) === undefined);
const output = { ...event, valid: missing.length === 0, validationErrors: missing, status: missing.length === 0 ? event.status : 'failed', summary: missing.length === 0 ? event.summary : 'Payload missing required fields: ' + missing.join(', ') };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const issue = event.payload?.issue ?? {};
const body = String(issue.body ?? '');
const forbiddenPatterns = ['.env', '.env.local', 'secrets', 'production db config', '/api/session', '/api/ledger', '/api/bucket', '/api/payment', '/api/card'];
const forbiddenMatches = forbiddenPatterns.filter((pattern) => body.toLowerCase().includes(pattern.toLowerCase()));
const task = { source: 'github_issue_openclaw', repo: event.repo, issueNumber: issue.number, title: issue.title, url: issue.html_url, body, constraints: { advisoryOnly: true, forbiddenFiles: ['.env', '.env.local'], forbiddenEndpointPatterns: ['/api/session*', '/api/ledger*', '/api/bucket*', '/api/payment*', '/api/card*', '/api/debt*/mutate'], requiredReviewLabels: ['needs-human-review'] }, forbiddenMatches };
const output = { ...event, openclawTask: task, commentBody: { body: 'OpenClaw task prepared.\n\nIssue: #' + issue.number + '\nForbidden hints: ' + (forbiddenMatches.join(', ') || 'none') + '\nHuman review remains required before merge.' }, status: forbiddenMatches.length > 0 ? 'failed' : 'accepted', summary: forbiddenMatches.length > 0 ? 'OpenClaw issue contains forbidden-change hints.' : 'OpenClaw task routed for issue #' + issue.number + '.', actions: forbiddenMatches.length > 0 ? ['block_openclaw_task', 'comment_issue', 'archive_event'] : ['send_openclaw_task', 'comment_issue', 'archive_event'] };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ...event, workflow: event.workflow ?? '02_openclaw_issue_router', sinkRouting: {
  discord: '{{ $env.DISCORD_WEBHOOK_URL }}', slack: '{{ $env.SLACK_WEBHOOK_URL }}', email: '{{ $env.EMAIL_WEBHOOK_URL }}', notion: '{{ $env.NOTION_WEBHOOK_URL }}', googleSheets: '{{ $env.GOOGLE_SHEETS_WEBHOOK_URL }}', linearJira: '{{ $env.LINEAR_JIRA_WEBHOOK_URL }}', githubProjects: '{{ $env.GITHUB_PROJECTS_WEBHOOK_URL }}', archive: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/events', incidentTimeline: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/incident-timeline' } };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ok: event.ok !== false, workflow: event.workflow, status: event.status ?? 'accepted', summary: event.summary ?? 'OpenClaw issue routed.', actions: event.actions ?? [] };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ok: event.ok !== false, workflow: event.workflow, status: 'ignored', summary: event.summary ?? 'Issue was not labeled openclaw; no action taken.', actions: event.actions ?? [] };
return [{ json: output }];
